public class BigFraction_floatValue_TriageGen5Test {

    private static final float EPSILON = 1e-7f;

















    @Test
    public void testFloatValue_PrecisionLoss() {
        // A fraction that cannot be represented exactly in float
        // 1/3
        BigFraction fraction = new BigFraction(1, 3);
        float expected = (float) (1.0 / 3.0);
        assertEquals(expected, fraction.floatValue(), EPSILON);
    }
